INSERT INTO Receita
(id, idEmpresa, idUsuario, nome, descricao, modoPreparo, dtReceita, foiFeita)
VALUES
(1, NULL, '34901483714', 'Strogonoff de frango', 'Clássico de domingo, cremoso e rápido de fazer.', 'Refogue a cebola picada no óleo, junte o frango em cubos temperado com sal e doure bem. Acrescente o extrato de tomate, os cogumelos e deixe apurar por 5 minutos. Desligue o fogo, misture o creme de leite e sirva com arroz branco.', '2026-05-19', true),
(2, NULL, '13055120060', 'Bolo de cenoura com cobertura de chocolate', 'Bolo fofinho para o café da tarde.', 'Bata no liquidificador a cenoura, os ovos e o óleo. Misture com o açúcar e a farinha, acrescente o fermento e asse em forma untada por 40 minutos. Para a cobertura, leve ao fogo o cacau, o açúcar e a manteiga até engrossar e despeje sobre o bolo morno.', '2026-08-14', false),
(3, NULL, '91208756303', 'Macarrão à bolonhesa', 'Receita básica para a semana corrida.', 'Cozinhe o espaguete em água com sal até ficar al dente. Refogue cebola e alho, junte a carne moída e deixe dourar. Acrescente o molho de tomate, o orégano e cozinhe em fogo baixo por 15 minutos. Misture à massa e finalize com parmesão.', '2026-09-22', true),
(4, NULL, '69362392690', 'Frango assado com batatas', 'Prato de forno que não exige atenção.', 'Tempere as coxas e sobrecoxas com alho, colorau, sal e pimenta e deixe descansar por 30 minutos. Disponha em assadeira com as batatas em pedaços, regue com azeite e asse a 200 graus por 50 minutos, virando na metade do tempo.', '2026-09-14', false),
(5, NULL, '47516028967', 'Omelete de queijo e tomate', 'Ótima opção de café da manhã ou jantar leve.', 'Bata os ovos com uma pitada de sal. Aqueça uma frigideira antiaderente, despeje os ovos e distribua a mussarela, o tomate em cubos e o cheiro-verde. Dobre ao meio quando o queijo derreter.', '2026-06-09', true),
(6, NULL, '25669665244', 'Panqueca de carne moída', 'Panquecas macias com recheio suculento.', 'Misture farinha, ovos, leite e sal até obter uma massa lisa e frite discos finos em frigideira untada. Refogue a carne moída com cebola e molho de tomate. Recheie, enrole, cubra com molho e mussarela e gratine.', '2026-09-09', false),
(7, NULL, '03823301535', 'Lasanha de presunto e queijo', 'Versão prática, sem carne.', 'Prepare um molho branco com manteiga, farinha e leite. Em refratário, intercale camadas de massa, presunto, mussarela, molho de tomate e molho branco. Finalize com queijo e leve ao forno a 200 graus por 30 minutos.', '2026-09-02', true),
(8, NULL, '81976937817', 'Feijoada caseira', 'Para o sábado com a família.', 'Deixe a carne seca de molho na véspera. Cozinhe o feijão preto com louro até amaciar. Frite bacon, linguiça e cebola, junte a carne seca picada e misture ao feijão. Cozinhe por mais 40 minutos e sirva com arroz e couve.', '2026-09-18', true),
(9, NULL, '60130574198', 'Salada tropical', 'Refrescante e colorida.', 'Lave e corte a alface, o tomate e a cenoura ralada. Acrescente manga em cubos, tempere com azeite, suco de limão e sal na hora de servir.', '2026-08-19', false),
(10, NULL, '38284210401', 'Salmão grelhado com legumes', 'Jantar leve e nutritivo.', 'Tempere as postas de salmão com sal e limão. Grelhe por 4 minutos de cada lado. Refogue brócolis e abobrinha no azeite e sirva com o peixe.', '2026-07-24', true),
(11, NULL, '16437846763', 'Risoto de frango', 'Cremoso e reconfortante.', 'Refogue cebola e alho na manteiga, junte o arroz e mexa. Vá adicionando caldo quente aos poucos, mexendo, até ficar cremoso. Acrescente o frango já cozido e desfiado, o parmesão e finalize com cheiro-verde.', '2026-08-29', false),
(12, NULL, '94591483010', 'Purê de batata cremoso', 'Acompanhamento clássico.', 'Cozinhe as batatas descascadas até ficarem macias, escorra e amasse. Volte à panela com manteiga e leite morno, mexendo até obter textura cremosa. Acerte o sal.', '2026-09-27', true),
(13, NULL, '72745119397', 'Pudim de leite condensado', 'Sobremesa tradicional de festa.', 'Bata no liquidificador o leite condensado, o leite e os ovos. Faça um caramelo com açúcar em forma de pudim, despeje a mistura e asse em banho-maria por 50 minutos. Leve à geladeira por 4 horas antes de desenformar.', '2026-03-08', false),
(14, NULL, '50898755611', 'Mousse de maracujá', 'Cremosa e fácil, só três ingredientes.', 'Bata no liquidificador o suco de maracujá, o leite condensado e o creme de leite. Despeje em taças e leve à geladeira por pelo menos 3 horas.', '2025-12-07', true),
(15, NULL, '29052391904', 'Brigadeiro tradicional', 'Clássico para aniversários.', 'Em panela de fundo grosso, misture leite condensado, cacau e manteiga. Cozinhe mexendo até soltar do fundo. Deixe esfriar, modele as bolinhas e passe no chocolate granulado.', '2026-08-07', true),
(16, NULL, '07206028233', 'Torta de frango com requeijão', 'Receita de liquidificador.', 'Bata ovos, leite, óleo e farinha, junte o fermento. Misture o frango refogado com requeijão, milho e extrato de tomate. Monte em camadas e asse a 180 graus por 40 minutos.', '2026-10-01', false),
(17, NULL, '98380644590', 'Escondidinho de carne seca', 'Prato de forno típico do almoço de fim de semana.', 'Cozinhe a mandioca e amasse com manteiga. Refogue a carne seca desfiada com cebola. Monte em refratário com carne no fundo, purê por cima, cubra com mussarela e gratine.', '2026-07-31', true),
(18, NULL, '76534280884', 'Vitamina de banana com aveia', 'Café da manhã rápido.', 'Bata no liquidificador a banana, o leite, o iogurte e a aveia até ficar homogêneo. Sirva gelada.', '2026-07-06', false),
(19, NULL, '54687917143', 'Limonada suíça', 'Bebida cremosa para dias quentes.', 'Bata o limão com casca por poucos segundos com água gelada, leite condensado e açúcar. Coe e sirva com gelo.', '2026-10-03', true),
(20, NULL, '32841553418', 'Tilápia ao molho de limão', 'Leve e pronto em 20 minutos.', 'Tempere os filés com sal, alho e limão. Grelhe na manteiga até dourar. Faça um molho com mais manteiga, suco de limão e cheiro-verde e regue o peixe.', '2026-10-04', false),
(21, NULL, '10995189706', 'Panqueca de banana e aveia', 'Sem farinha de trigo.', 'Amasse a banana, misture com os ovos, a aveia e a canela. Doure em frigideira antiaderente dos dois lados e sirva com iogurte.', '2026-05-19', true),
(22, NULL, '89148826081', 'Mingau de aveia', 'Quentinho nos dias frios.', 'Leve ao fogo o leite com a aveia, mexendo até engrossar. Adoce com açúcar e finalize com canela.', '2026-08-14', true),
(23, NULL, '67302462356', 'Picanha na brasa com farofa', 'Churrasco de domingo.', 'Corte a picanha em bifes grossos e salgue com sal grosso. Grelhe na brasa até o ponto desejado. Para a farofa, frite bacon e cebola, junte a farinha de mandioca e ovos mexidos.', '2026-09-22', false),
(24, NULL, '45456098644', 'Espetinho misto', 'Perfeito para a churrasqueira.', 'Corte a alcatra, o queijo coalho, o pimentão e a cebola em cubos e monte os espetos alternando os ingredientes. Tempere com sal grosso e grelhe virando sempre.', '2026-09-14', true),
(25, NULL, '23609734957', 'Vinagrete', 'Acompanhamento obrigatório do churrasco.', 'Pique o tomate, a cebola e o pimentão em cubos pequenos, misture com cheiro-verde, vinagre, azeite e sal. Deixe descansar 30 minutos.', '2026-06-09', false),
(26, NULL, '01763371212', 'Sopa de legumes', 'Ideal para noites frias.', 'Refogue cebola e alho, adicione batata, cenoura e abobrinha em cubos e cubra com água. Cozinhe até amaciar, junte um punhado de macarrão e cozinhe por mais 8 minutos.', '2026-09-09', true),
(27, NULL, '79917007555', 'Caldo de feijão', 'Rápido e saboroso.', 'Cozinhe o feijão e bata parte no liquidificador. Volte à panela, junte bacon e linguiça fritos com cebola e alho e deixe ferver. Finalize com cheiro-verde.', '2026-09-02', false),
(28, NULL, '58070643803', 'Hambúrguer caseiro', 'Lanche de sábado à noite.', 'Modele a carne moída temperada em discos e grelhe em frigideira bem quente. Monte no pão com queijo, alface, tomate e maionese.', '2026-09-18', true),
(29, NULL, '36224280150', 'Pizza de frigideira', 'Pizza rápida quando bate a vontade.', 'Misture farinha, fermento, leite e óleo até formar massa. Abra em disco, doure de um lado na frigideira, vire, cubra com molho, presunto, mussarela e orégano e tampe até derreter.', '2026-08-19', true),
(30, NULL, '14377916467', 'Quiche de legumes', 'Boa para lanche ou jantar.', 'Prepare uma massa com farinha, manteiga e um ovo e forre a forma. Refogue brócolis, misture com ovos, creme de leite e parmesão, despeje e asse a 180 graus por 35 minutos.', '2026-07-24', false),
(31, NULL, '92531552723', 'Ovos mexidos com bacon', 'Café reforçado.', 'Frite o bacon até ficar crocante. Em outra frigideira, mexa os ovos na manteiga em fogo baixo. Sirva com pão de forma tostado.', '2026-08-29', true),
(32, NULL, '83706169096', 'Bife acebolado', 'Prato simples do dia a dia.', 'Tempere os bifes com sal e alho. Frite rapidamente em óleo bem quente. Na mesma frigideira, doure a cebola em rodelas e sirva por cima.', '2026-09-27', false),
(33, NULL, '61859805337', 'Carne de panela com batatas', 'Cozida lentamente, bem macia.', 'Doure a carne em cubos na panela de pressão, junte cebola, extrato de tomate e louro. Acrescente água e cozinhe por 30 minutos. Adicione batata e cenoura e cozinhe por mais 10.', '2026-03-08', true),
(34, NULL, '40013441655', 'Costelinha com mandioca', 'Almoço de domingo clássico.', 'Tempere a costelinha com alho e mostarda e deixe marinar. Asse coberta com papel alumínio por 1h30. Cozinhe a mandioca e sirva junto, finalizando com cheiro-verde.', '2025-12-07', false),
(35, NULL, '18167077918', 'Salada de maionese', 'Acompanha qualquer festa.', 'Cozinhe batata e cenoura em cubos. Misture com ervilha, cebola picada e maionese. Tempere com sal e leve à geladeira.', '2026-08-07', true),
(36, NULL, '96320714255', 'Arroz de forno', 'Aproveita sobras e vai bem em almoços.', 'Misture o arroz cozido com presunto, milho, ervilha e creme de leite. Cubra com mussarela e leve ao forno até gratinar.', '2026-10-01', true),
(37, NULL, '74474350588', 'Frango xadrez', 'Inspirado na cozinha oriental.', 'Doure o filé de frango em cubos. Adicione pimentão e cebola e refogue em fogo alto. Misture shoyu dissolvido com amido de milho e água e cozinhe até engrossar.', '2026-07-31', false),
(38, NULL, '52627986830', 'Tilápia assada com batata-doce', 'Refeição completa no forno.', 'Tempere os filés com limão, alho e sal. Disponha em assadeira com batata-doce em rodelas e regue com azeite. Asse a 200 graus por 30 minutos.', '2026-07-06', true),
(39, NULL, '30781623111', 'Bolo de fubá cremoso', 'Perfeito para acompanhar o café.', 'Bata no liquidificador leite, óleo, ovos, açúcar e fubá. Junte a farinha e o fermento. Asse em forma untada por 40 minutos.', '2026-10-03', false),
(40, NULL, '08935259446', 'Bruschetta de tomate', 'Entrada simples.', 'Corte o pão em fatias e toste. Misture tomate picado com alho, azeite e orégano. Cubra as fatias e finalize com mussarela derretida.', '2026-10-04', true),
(41, NULL, '87088895706', 'Salada de frutas com iogurte', 'Sobremesa leve.', 'Pique maçã, banana, laranja, mamão e uva e misture delicadamente. Sirva gelada com iogurte natural por cima.', '2026-05-19', false),
(42, NULL, '65242532050', 'Smoothie de morango', 'Rápido e proteico.', 'Bata morangos congelados com iogurte grego e leite sem lactose até ficar cremoso.', '2026-08-14', true),
(43, NULL, '43396168348', 'Wrap de frango', 'Almoço rápido para levar.', 'Grelhe o frango em tiras. Espalhe requeijão no pão, acrescente o frango, alface e tomate e enrole.', '2026-09-22', true),
(44, NULL, '21549804650', 'Pizza caseira de calabresa', 'Para a noite de pizza em casa.', 'Abra a massa pronta, cubra com molho de tomate, mussarela, rodelas de calabresa e cebola. Asse a 220 graus até dourar as bordas e finalize com orégano.', '2026-09-14', false),
(45, NULL, '99703440991', 'Brownie de chocolate', 'Sobremesa intensa.', 'Derreta o chocolate amargo com a manteiga. Misture açúcar, ovos e farinha. Asse em forma pequena por 25 minutos para que fique úmido no centro.', '2026-06-09', true),
(46, NULL, '77857077232', 'Açaí na tigela', 'Café da manhã ou lanche pós-treino.', 'Bata a polpa de açaí congelada com banana até ficar cremoso. Sirva na tigela com morango picado e aveia.', '2026-09-09', false),
(47, NULL, '69031693502', 'Moqueca de peixe', 'Prato leve e perfumado.', 'Disponha camadas de pescada, tomate, pimentão e cebola em panela larga. Regue com azeite e leite de coco, cozinhe tampado por 20 minutos e finalize com cheiro-verde.', '2026-09-02', true),
(48, NULL, '47185329817', 'Bacalhau ao forno', 'Prato tradicional para datas especiais.', 'Disponha batatas em rodelas e cebola em camadas, coloque as lascas de bacalhau dessalgado, azeitonas pretas e ovos cozidos. Regue com azeite e asse por 40 minutos.', '2026-09-18', false),
(49, NULL, '25338966166', 'Estrogonofe de carne', 'Versão clássica com carne bovina.', 'Doure a alcatra em tiras, junte cebola, extrato de tomate e cogumelos. Desligue o fogo e misture o creme de leite.', '2026-08-19', true),
(50, NULL, '03492602495', 'Almôndegas ao molho', 'Favorita das crianças.', 'Misture carne moída, ovo, farinha de rosca, cebola e alho picados e modele as bolinhas. Doure e cozinhe no molho de tomate por 15 minutos.', '2026-07-24', true);

INSERT INTO Receita
(id, idEmpresa, idUsuario, nome, descricao, modoPreparo, dtReceita, foiFeita)
VALUES
(51, NULL, '81646238737', 'Macarrão alho e óleo', 'Pronto em 15 minutos.', 'Cozinhe o espaguete. Doure o alho laminado no azeite com pimenta calabresa, misture a massa e finalize com cheiro-verde.', '2026-08-29', false),
(52, NULL, '59799875099', 'Sanduíche natural', 'Lanche leve para a tarde.', 'Misture a ricota amassada com cenoura ralada. Recheie o pão de forma com peito de peru, a pasta de ricota e alface.', '2026-09-27', true),
(53, NULL, '37953511380', 'Salada Caesar com frango', 'Clássica e completa.', 'Grelhe o frango e corte em tiras. Monte a salada com alface americana, croutons de pão de forma tostado e parmesão. Tempere com molho de maionese, limão e pimenta.', '2026-03-08', false),
(54, NULL, '16107147683', 'Feijão tropeiro', 'Receita mineira para o almoço.', 'Frite bacon e linguiça, junte o feijão cozido e a farinha de mandioca aos poucos. Acrescente ovos mexidos e finalize com cheiro-verde.', '2025-12-07', true),
(55, NULL, '94260783980', 'Torta salgada de liquidificador', 'Prática para o lanche.', 'Bata ovos, leite, óleo e farinha e junte o fermento. Misture parte da massa com atum e milho, despeje em forma e cubra com o restante da massa. Asse por 40 minutos.', '2026-08-07', false),
(56, NULL, '72414420243', 'Bolo de laranja', 'Cheiroso e úmido.', 'Bata no liquidificador as laranjas com casca, o óleo e os ovos. Misture com açúcar e farinha, junte o fermento e asse por 40 minutos.', '2026-10-01', true),
(57, NULL, '50568056531', 'Mousse de chocolate caseira', 'Sobremesa elegante.', 'Derreta o chocolate amargo e deixe amornar. Misture o creme de leite e as claras em neve delicadamente. Leve à geladeira por 4 horas.', '2026-07-31', true),
(58, NULL, '28721692882', 'Pavê de chocolate', 'Receita de festa.', 'Prepare um creme com leite, leite condensado e cacau e engrosse no fogo. Monte camadas alternando creme e creme de leite batido, finalize com chocolate granulado e gele.', '2026-07-06', false),
(59, NULL, '06875329140', 'Gelatina com frutas', 'Sobremesa econômica.', 'Prepare a gelatina conforme a embalagem. Quando começar a firmar, acrescente morangos e banana em pedaços e leve para gelar.', '2026-10-03', true),
(60, NULL, '85028965471', 'Bowl de ovos e legumes', 'Refeição leve e proteica.', 'Cozinhe os ovos por 8 minutos. Monte o bowl com batata-doce assada, brócolis no vapor, tomate e regue com azeite.', '2026-10-04', false),
(61, NULL, '63182601709', 'Pão de queijo com requeijão', 'Lanche da tarde.', 'Aqueça os pães de queijo no forno até dourar e sirva com requeijão cremoso.', '2026-05-19', true),
(62, NULL, '41336238003', 'Strogonoff de frango', 'Clássico de domingo, cremoso e rápido de fazer.', 'Refogue a cebola picada no óleo, junte o frango em cubos temperado com sal e doure bem. Acrescente o extrato de tomate, os cogumelos e deixe apurar por 5 minutos. Desligue o fogo, misture o creme de leite e sirva com arroz branco.', '2026-08-14', false),
(63, NULL, '32510854330', 'Bolo de cenoura com cobertura de chocolate', 'Bolo fofinho para o café da tarde.', 'Bata no liquidificador a cenoura, os ovos e o óleo. Misture com o açúcar e a farinha, acrescente o fermento e asse em forma untada por 40 minutos. Para a cobertura, leve ao fogo o cacau, o açúcar e a manteiga até engrossar e despeje sobre o bolo morno.', '2026-09-22', true),
(64, NULL, '10664490662', 'Macarrão à bolonhesa', 'Receita básica para a semana corrida.', 'Cozinhe o espaguete em água com sal até ficar al dente. Refogue cebola e alho, junte a carne moída e deixe dourar. Acrescente o molho de tomate, o orégano e cozinhe em fogo baixo por 15 minutos. Misture à massa e finalize com parmesão.', '2026-09-14', true),
