(71, NULL, '57739944700', 'Salmão grelhado com legumes', 'Jantar leve e nutritivo.', 'Tempere as postas de salmão com sal e limão. Grelhe por 4 minutos de cada lado. Refogue brócolis e abobrinha no azeite e sirva com o peixe.', '2026-08-29', true),
(72, NULL, '35893581067', 'Risoto de frango', 'Cremoso e reconfortante.', 'Refogue cebola e alho na manteiga, junte o arroz e mexa. Vá adicionando caldo quente aos poucos, mexendo, até ficar cremoso. Acrescente o frango já cozido e desfiado, o parmesão e finalize com cheiro-verde.', '2026-09-27', false),
(73, NULL, '14047217387', 'Purê de batata cremoso', 'Acompanhamento clássico.', 'Cozinhe as batatas descascadas até ficarem macias, escorra e amasse. Volte à panela com manteiga e leite morno, mexendo até obter textura cremosa. Acerte o sal.', '2026-03-08', true),
(74, NULL, '92200853645', 'Pudim de leite condensado', 'Sobremesa tradicional de festa.', 'Bata no liquidificador o leite condensado, o leite e os ovos. Faça um caramelo com açúcar em forma de pudim, despeje a mistura e asse em banho-maria por 50 minutos. Leve à geladeira por 4 horas antes de desenformar.', '2025-12-07', false),
(75, NULL, '70354489933', 'Mousse de maracujá', 'Cremosa e fácil, só três ingredientes.', 'Bata no liquidificador o suco de maracujá, o leite condensado e o creme de leite. Despeje em taças e leve à geladeira por pelo menos 3 horas.', '2026-08-07', true),
(76, NULL, '48508126271', 'Brigadeiro tradicional', 'Clássico para aniversários.', 'Em panela de fundo grosso, misture leite condensado, cacau e manteiga. Cozinhe mexendo até soltar do fundo. Deixe esfriar, modele as bolinhas e passe no chocolate granulado.', '2026-10-01', false),
(77, NULL, '26661762586', 'Torta de frango com requeijão', 'Receita de liquidificador.', 'Bata ovos, leite, óleo e farinha, junte o fermento. Misture o frango refogado com requeijão, milho e extrato de tomate. Monte em camadas e asse a 180 graus por 40 minutos.', '2026-07-31', true),
(78, NULL, '17836378896', 'Escondidinho de carne seca', 'Prato de forno típico do almoço de fim de semana.', 'Cozinhe a mandioca e amasse com manteiga. Refogue a carne seca desfiada com cebola. Monte em refratário com carne no fundo, purê por cima, cubra com mussarela e gratine.', '2026-07-06', true),
(79, NULL, '95990015160', 'Vitamina de banana com aveia', 'Café da manhã rápido.', 'Bata no liquidificador a banana, o leite, o iogurte e a aveia até ficar homogêneo. Sirva gelada.', '2026-10-03', false),
(80, NULL, '74143651408', 'Limonada suíça', 'Bebida cremosa para dias quentes.', 'Bata o limão com casca por poucos segundos com água gelada, leite condensado e açúcar. Coe e sirva com gelo.', '2026-10-04', true),
(81, NULL, '52297287798', 'Tilápia ao molho de limão', 'Leve e pronto em 20 minutos.', 'Tempere os filés com sal, alho e limão. Grelhe na manteiga até dourar. Faça um molho com mais manteiga, suco de limão e cheiro-verde e regue o peixe.', '2026-05-19', false),
(82, NULL, '30450924033', 'Panqueca de banana e aveia', 'Sem farinha de trigo.', 'Amasse a banana, misture com os ovos, a aveia e a canela. Doure em frigideira antiaderente dos dois lados e sirva com iogurte.', '2026-08-14', true),
(83, NULL, '08604560300', 'Mingau de aveia', 'Quentinho nos dias frios.', 'Leve ao fogo o leite com a aveia, mexendo até engrossar. Adoce com açúcar e finalize com canela.', '2026-09-22', false),
(84, NULL, '86758196682', 'Picanha na brasa com farofa', 'Churrasco de domingo.', 'Corte a picanha em bifes grossos e salgue com sal grosso. Grelhe na brasa até o ponto desejado. Para a farofa, frite bacon e cebola, junte a farinha de mandioca e ovos mexidos.', '2026-09-14', true),
(85, NULL, '64911832975', 'Espetinho misto', 'Perfeito para a churrasqueira.', 'Corte a alcatra, o queijo coalho, o pimentão e a cebola em cubos e monte os espetos alternando os ingredientes. Tempere com sal grosso e grelhe virando sempre.', '2026-06-09', true),
(86, NULL, '43065469260', 'Vinagrete', 'Acompanhamento obrigatório do churrasco.', 'Pique o tomate, a cebola e o pimentão em cubos pequenos, misture com cheiro-verde, vinagre, azeite e sal. Deixe descansar 30 minutos.', '2026-09-09', false),
(87, NULL, '21219105570', 'Sopa de legumes', 'Ideal para noites frias.', 'Refogue cebola e alho, adicione batata, cenoura e abobrinha em cubos e cubra com água. Cozinhe até amaciar, junte um punhado de macarrão e cozinhe por mais 8 minutos.', '2026-09-02', true),
(88, NULL, '99372741841', 'Caldo de feijão', 'Rápido e saboroso.', 'Cozinhe o feijão e bata parte no liquidificador. Volte à panela, junte bacon e linguiça fritos com cebola e alho e deixe ferver. Finalize com cheiro-verde.', '2026-09-18', false),
(89, NULL, '77526378154', 'Hambúrguer caseiro', 'Lanche de sábado à noite.', 'Modele a carne moída temperada em discos e grelhe em frigideira bem quente. Monte no pão com queijo, alface, tomate e maionese.', '2026-08-19', true),
(90, NULL, '55680014483', 'Pizza de frigideira', 'Pizza rápida quando bate a vontade.', 'Misture farinha, fermento, leite e óleo até formar massa. Abra em disco, doure de um lado na frigideira, vire, cubra com molho, presunto, mussarela e orégano e tampe até derreter.', '2026-07-24', false),
(91, NULL, '33833650770', 'Quiche de legumes', 'Boa para lanche ou jantar.', 'Prepare uma massa com farinha, manteiga e um ovo e forre a forma. Refogue brócolis, misture com ovos, creme de leite e parmesão, despeje e asse a 180 graus por 35 minutos.', '2026-08-29', true),
(92, NULL, '11987287010', 'Ovos mexidos com bacon', 'Café reforçado.', 'Frite o bacon até ficar crocante. Em outra frigideira, mexa os ovos na manteiga em fogo baixo. Sirva com pão de forma tostado.', '2026-09-27', true),
(93, NULL, '90140923349', 'Bife acebolado', 'Prato simples do dia a dia.', 'Tempere os bifes com sal e alho. Frite rapidamente em óleo bem quente. Na mesma frigideira, doure a cebola em rodelas e sirva por cima.', '2026-03-08', false),
(94, NULL, '81315539659', 'Carne de panela com batatas', 'Cozida lentamente, bem macia.', 'Doure a carne em cubos na panela de pressão, junte cebola, extrato de tomate e louro. Acrescente água e cozinhe por 30 minutos. Adicione batata e cenoura e cozinhe por mais 10.', '2025-12-07', true),
(95, NULL, '59469175956', 'Costelinha com mandioca', 'Almoço de domingo clássico.', 'Tempere a costelinha com alho e mostarda e deixe marinar. Asse coberta com papel alumínio por 1h30. Cozinhe a mandioca e sirva junto, finalizando com cheiro-verde.', '2026-08-07', false),
(96, NULL, '37622812200', 'Salada de maionese', 'Acompanha qualquer festa.', 'Cozinhe batata e cenoura em cubos. Misture com ervilha, cebola picada e maionese. Tempere com sal e leve à geladeira.', '2026-10-01', true),
(97, NULL, '15776448590', 'Arroz de forno', 'Aproveita sobras e vai bem em almoços.', 'Misture o arroz cozido com presunto, milho, ervilha e creme de leite. Cubra com mussarela e leve ao forno até gratinar.', '2026-07-31', false),
(98, NULL, '93930084856', 'Frango xadrez', 'Inspirado na cozinha oriental.', 'Doure o filé de frango em cubos. Adicione pimentão e cebola e refogue em fogo alto. Misture shoyu dissolvido com amido de milho e água e cozinhe até engrossar.', '2026-07-06', true),
(99, NULL, '72083721101', 'Tilápia assada com batata-doce', 'Refeição completa no forno.', 'Tempere os filés com limão, alho e sal. Disponha em assadeira com batata-doce em rodelas e regue com azeite. Asse a 200 graus por 30 minutos.', '2026-10-03', true),
(100, NULL, '50237357453', 'Bolo de fubá cremoso', 'Perfeito para acompanhar o café.', 'Bata no liquidificador leite, óleo, ovos, açúcar e fubá. Junte a farinha e o fermento. Asse em forma untada por 40 minutos.', '2026-10-04', false);

INSERT INTO Receita
(id, idEmpresa, idUsuario, nome, descricao, modoPreparo, dtReceita, foiFeita)
VALUES
(101, NULL, '28390993732', 'Bruschetta de tomate', 'Entrada simples.', 'Corte o pão em fatias e toste. Misture tomate picado com alho, azeite e orégano. Cubra as fatias e finalize com mussarela derretida.', '2026-05-19', true),
(102, NULL, '06544630004', 'Salada de frutas com iogurte', 'Sobremesa leve.', 'Pique maçã, banana, laranja, mamão e uva e misture delicadamente. Sirva gelada com iogurte natural por cima.', '2026-08-14', false),
(103, NULL, '84698266386', 'Smoothie de morango', 'Rápido e proteico.', 'Bata morangos congelados com iogurte grego e leite sem lactose até ficar cremoso.', '2026-09-22', true),
(104, NULL, '62851902679', 'Wrap de frango', 'Almoço rápido para levar.', 'Grelhe o frango em tiras. Espalhe requeijão no pão, acrescente o frango, alface e tomate e enrole.', '2026-09-14', false),
(105, NULL, '41005538972', 'Pizza caseira de calabresa', 'Para a noite de pizza em casa.', 'Abra a massa pronta, cubra com molho de tomate, mussarela, rodelas de calabresa e cebola. Asse a 220 graus até dourar as bordas e finalize com orégano.', '2026-06-09', true),
(106, NULL, '19159175222', 'Brownie de chocolate', 'Sobremesa intensa.', 'Derreta o chocolate amargo com a manteiga. Misture açúcar, ovos e farinha. Asse em forma pequena por 25 minutos para que fique úmido no centro.', '2026-09-09', true),
(107, NULL, '97312811507', 'Açaí na tigela', 'Café da manhã ou lanche pós-treino.', 'Bata a polpa de açaí congelada com banana até ficar cremoso. Sirva na tigela com morango picado e aveia.', '2026-09-02', false),
(108, NULL, '75466447803', 'Moqueca de peixe', 'Prato leve e perfumado.', 'Disponha camadas de pescada, tomate, pimentão e cebola em panela larga. Regue com azeite e leite de coco, cozinhe tampado por 20 minutos e finalize com cheiro-verde.', '2026-09-18', true),
(109, NULL, '66641064182', 'Bacalhau ao forno', 'Prato tradicional para datas especiais.', 'Disponha batatas em rodelas e cebola em camadas, coloque as lascas de bacalhau dessalgado, azeitonas pretas e ovos cozidos. Regue com azeite e asse por 40 minutos.', '2026-08-19', false),
(110, NULL, '44794700423', 'Estrogonofe de carne', 'Versão clássica com carne bovina.', 'Doure a alcatra em tiras, junte cebola, extrato de tomate e cogumelos. Desligue o fogo e misture o creme de leite.', '2026-07-24', true),
(111, NULL, '22948336783', 'Almôndegas ao molho', 'Favorita das crianças.', 'Misture carne moída, ovo, farinha de rosca, cebola e alho picados e modele as bolinhas. Doure e cozinhe no molho de tomate por 15 minutos.', '2026-08-29', false),
(112, NULL, '01101973056', 'Macarrão alho e óleo', 'Pronto em 15 minutos.', 'Cozinhe o espaguete. Doure o alho laminado no azeite com pimenta calabresa, misture a massa e finalize com cheiro-verde.', '2026-09-27', true),
(113, NULL, '79255609327', 'Sanduíche natural', 'Lanche leve para a tarde.', 'Misture a ricota amassada com cenoura ralada. Recheie o pão de forma com peito de peru, a pasta de ricota e alface.', '2026-03-08', true),
(114, NULL, '57409245611', 'Salada Caesar com frango', 'Clássica e completa.', 'Grelhe o frango e corte em tiras. Monte a salada com alface americana, croutons de pão de forma tostado e parmesão. Tempere com molho de maionese, limão e pimenta.', '2025-12-07', false),
(115, NULL, '35562881926', 'Feijão tropeiro', 'Receita mineira para o almoço.', 'Frite bacon e linguiça, junte o feijão cozido e a farinha de mandioca aos poucos. Acrescente ovos mexidos e finalize com cheiro-verde.', '2026-08-07', true),
(116, NULL, '13716518255', 'Torta salgada de liquidificador', 'Prática para o lanche.', 'Bata ovos, leite, óleo e farinha e junte o fermento. Misture parte da massa com atum e milho, despeje em forma e cubra com o restante da massa. Asse por 40 minutos.', '2026-10-01', false),
(117, NULL, '91870154550', 'Bolo de laranja', 'Cheiroso e úmido.', 'Bata no liquidificador as laranjas com casca, o óleo e os ovos. Misture com açúcar e farinha, junte o fermento e asse por 40 minutos.', '2026-07-31', true),
(118, NULL, '70023790890', 'Mousse de chocolate caseira', 'Sobremesa elegante.', 'Derreta o chocolate amargo e deixe amornar. Misture o creme de leite e as claras em neve delicadamente. Leve à geladeira por 4 horas.', '2026-07-06', false),
(119, NULL, '48177427121', 'Pavê de chocolate', 'Receita de festa.', 'Prepare um creme com leite, leite condensado e cacau e engrosse no fogo. Monte camadas alternando creme e creme de leite batido, finalize com chocolate granulado e gele.', '2026-10-03', true),
(120, NULL, '26331063404', 'Gelatina com frutas', 'Sobremesa econômica.', 'Prepare a gelatina conforme a embalagem. Quando começar a firmar, acrescente morangos e banana em pedaços e leve para gelar.', '2026-10-04', true),
(121, 'WZUFW710000112', NULL, 'Pizza Margherita', 'Receita da casa, com molho pizzaiolo.', 'Abra a massa, espalhe o molho de tomate pizzaiolo, distribua mussarela em fatias e tomate. Leve ao forno a 300 graus por 3 a 4 minutos e finalize com orégano e fio de azeite.', '2026-05-19', false),
(122, 'LQMTSF20000189', NULL, 'Pizza de calabresa', 'Campeã de vendas do cardápio.', 'Estenda a massa, cubra com molho, mussarela e calabresa em rodelas finas. Adicione cebola e azeitonas e leve ao forno bem quente por 4 minutos.', '2026-08-14', true),
(123, 'AHE7PN30000156', NULL, 'Pizza quatro queijos', 'Mistura de queijos selecionados.', 'Sobre a massa com molho leve, distribua mussarela, gorgonzola, parmesão e requeijão. Asse até dourar e finalize com orégano.', '2026-09-22', false),
(124, 'Z76LLV40000140', NULL, 'Pizza de frango com requeijão', 'Sabor popular entre as famílias.', 'Cubra a massa com molho, frango desfiado temperado, mussarela e fios de requeijão. Asse até as bordas dourarem.', '2026-09-14', true),
(125, 'DPPCEB70000125', NULL, 'Pizza portuguesa', 'Receita tradicional com ovos e presunto.', 'Sobre a massa com molho, distribua presunto, mussarela, cebola, pimentão, azeitona verde e ovos cozidos fatiados. Asse por 4 minutos.', '2026-06-09', false),
(126, '91215468000159', NULL, 'Pizza Margherita', 'Receita da casa, com molho pizzaiolo.', 'Abra a massa, espalhe o molho de tomate pizzaiolo, distribua mussarela em fatias e tomate. Leve ao forno a 300 graus por 3 a 4 minutos e finalize com orégano e fio de azeite.', '2026-09-09', true),
(127, 'R6947R90000199', NULL, 'Pizza de calabresa', 'Campeã de vendas do cardápio.', 'Estenda a massa, cubra com molho, mussarela e calabresa em rodelas finas. Adicione cebola e azeitonas e leve ao forno bem quente por 4 minutos.', '2026-09-02', true),
(128, 'GX0I3ZA0000150', NULL, 'Pizza quatro queijos', 'Mistura de queijos selecionados.', 'Sobre a massa com molho leve, distribua mussarela, gorgonzola, parmesão e requeijão. Asse até dourar e finalize com orégano.', '2026-09-18', false),
(129, 'UEK9WED0000150', NULL, 'Smash burger duplo', 'Dois discos prensados na chapa.', 'Prense duas bolas de carne na chapa bem quente por 2 minutos de cada lado. Monte no pão brioche com queijo prato, cebola, picles e molhos.', '2026-08-19', true),
(130, 'J5CNSME0000150', NULL, 'Cheeseburger de picanha com bacon', 'Lanche premium da casa.', 'Grelhe o hambúrguer de picanha temperado, cubra com queijo e finalize com bacon crocante. Monte com alface, tomate e maionese da casa.', '2026-07-24', false),
(131, '8W31PUF0000102', NULL, 'Burger de frango crocante', 'Opção sem carne vermelha.', 'Frite o empanado de frango até dourar. Monte no pão com queijo, alface e maionese.', '2026-08-29', true),
(132, '97696028000147', NULL, 'Batata frita da casa', 'Acompanhamento de todos os lanches.', 'Frite a batata palito congelada em óleo a 180 graus até dourar. Escorra, tempere com sal e pimenta e sirva com molho.', '2026-09-27', false),
(133, 'B4F6EIJ0000120', NULL, 'Smash burger duplo', 'Dois discos prensados na chapa.', 'Prense duas bolas de carne na chapa bem quente por 2 minutos de cada lado. Monte no pão brioche com queijo prato, cebola, picles e molhos.', '2026-03-08', true),
(134, '0V6KAQK0000145', NULL, 'Cheeseburger de picanha com bacon', 'Lanche premium da casa.', 'Grelhe o hambúrguer de picanha temperado, cubra com queijo e finalize com bacon crocante. Monte com alface, tomate e maionese da casa.', '2025-12-07', true),
(135, 'PLYX6YL0000116', NULL, 'Burger de frango crocante', 'Opção sem carne vermelha.', 'Frite o empanado de frango até dourar. Monte no pão com queijo, alface e maionese.', '2026-08-07', false),
(136, 'ECQB36N0000121', NULL, 'Batata frita da casa', 'Acompanhamento de todos os lanches.', 'Frite a batata palito congelada em óleo a 180 graus até dourar. Escorra, tempere com sal e pimenta e sirva com molho.', '2026-10-01', true),
(137, '94717608000185', NULL, 'Pão na chapa com requeijão', 'Clássico do café da manhã.', 'Corte o pão francês ao meio, passe manteiga e toste na chapa. Sirva com requeijão cremoso.', '2026-07-31', false),
(138, 'HK1HSTQ0000174', NULL, 'Cappuccino cremoso', 'Bebida quente da casa.', 'Prepare o café coado forte, aqueça o leite com espuma e misture. Finalize com chantilly e cacau em pó.', '2026-07-06', true),
(139, '6BTUO1S0000170', NULL, 'Croque monsieur', 'Sanduíche quente gratinado.', 'Passe manteiga nas fatias de pão de forma, recheie com presunto e mussarela, cubra com creme de leite e queijo e gratine no forno.', '2026-10-03', false),
(140, 'V1L8L9T0000181', NULL, 'Bowl de frutas com iogurte', 'Opção leve do menu.', 'Em uma tigela, coloque iogurte grego, morango, banana e aveia. Sirva imediatamente.', '2026-10-04', true),
(141, '9J40EPV0000169', NULL, 'Pão na chapa com requeijão', 'Clássico do café da manhã.', 'Corte o pão francês ao meio, passe manteiga e toste na chapa. Sirva com requeijão cremoso.', '2026-05-19', true),
(142, 'Y9WDAXW0000199', NULL, 'Pão francês tradicional', 'Fornada diária da casa.', 'Misture farinha, fermento, sal e açúcar, adicione água e sove até obter massa lisa. Deixe crescer, modele e asse em forno a vapor a 220 graus por 20 minutos.', '2026-08-14', false),
(143, '98924398000157', NULL, 'Bolo simples de padaria', 'Vendido em fatias no balcão.', 'Bata ovos com açúcar, junte leite e margarina derretida, a farinha e o fermento. Asse por 45 minutos em forma grande.', '2026-09-22', true),
(144, 'CRF53DZ0000128', NULL, 'Sonho com creme', 'Fritura de fim de tarde.', 'Prepare a massa com farinha, leite, ovos e fermento, deixe crescer, frite e recheie com doce de leite.', '2026-09-14', false),
(145, 'Q8ZWVS11000170', NULL, 'Pão de leite', 'Macio e levemente adocicado.', 'Misture farinha, leite, manteiga, açúcar e fermento e sove. Deixe descansar, modele os pãezinhos, pincele com ovo e asse a 180 graus por 25 minutos.', '2026-06-09', true),
(146, 'FZQAS031000141', NULL, 'Misto quente de balcão', 'Sanduíche vendido o dia todo.', 'Passe manteiga no pão francês, recheie com presunto e mussarela e doure na chapa dos dois lados.', '2026-09-09', false),
(147, '4QIOO841000138', NULL, 'Pão francês tradicional', 'Fornada diária da casa.', 'Misture farinha, fermento, sal e açúcar, adicione água e sove até obter massa lisa. Deixe crescer, modele e asse em forno a vapor a 220 graus por 20 minutos.', '2026-09-02', true),
(148, 'TGA2LG51000183', NULL, 'Bolo simples de padaria', 'Vendido em fatias no balcão.', 'Bata ovos com açúcar, junte leite e margarina derretida, a farinha e o fermento. Asse por 45 minutos em forma grande.', '2026-09-18', true),
(149, '7YTTDW71000179', NULL, 'Bolo de chocolate com ganache', 'Bolo de aniversário mais pedido.', 'Misture farinha, cacau, açúcar e ovos e asse. Prepare a ganache aquecendo creme de leite e despejando sobre o chocolate amargo picado. Cubra o bolo resfriado.', '2026-08-19', false),
(150, 'WOL7A491000191', NULL, 'Torta de morango com chantilly', 'Sobremesa de vitrine.', 'Asse a base de massa amanteigada, recheie com creme de leite condensado, cubra com morangos e finalize com chantilly.', '2026-07-24', true);

INSERT INTO Receita
(id, idEmpresa, idUsuario, nome, descricao, modoPreparo, dtReceita, foiFeita)
VALUES
(151, 'LFDL6CA1000150', NULL, 'Brigadeiro gourmet', 'Produzido em lotes diários.', 'Cozinhe leite condensado, creme de leite, manteiga e chocolate amargo até o ponto de enrolar. Modele e passe no granulado.', '2026-08-29', false),
(152, 'A65Z2KB1000170', NULL, 'Mousse de maracujá em taça', 'Sobremesa fria de sucesso.', 'Bata a polpa de maracujá com leite condensado e creme de leite, distribua em taças e decore com a polpa.', '2026-09-27', true),
(153, 'ONOQVZD1000156', NULL, 'Cheesecake de frutas vermelhas', 'Receita de encomenda.', 'Prepare a base com manteiga e farinha, recheie com cream cheese batido com leite condensado e creme de leite, asse em banho-maria e cubra com calda de morango.', '2026-03-08', false),
(154, '99123509000199', NULL, 'Bolo de chocolate com ganache', 'Bolo de aniversário mais pedido.', 'Misture farinha, cacau, açúcar e ovos e asse. Prepare a ganache aquecendo creme de leite e despejando sobre o chocolate amargo picado. Cubra o bolo resfriado.', '2025-12-07', true),
(155, '258IOFG1000190', NULL, 'Marmita de frango grelhado', 'Prato executivo do dia.', 'Grelhe os filés temperados e sirva com arroz, feijão carioca, salada de alface e tomate.', '2026-08-07', true),
(156, 'RVZVKNH1000159', NULL, 'Marmita de carne de panela', 'Opção caseira de segunda a sexta.', 'Cozinhe o acém com batata e cenoura em molho encorpado. Sirva com arroz e feijão.', '2026-10-01', false),
(157, '5DJND3K1000150', NULL, 'Feijoada completa de sábado', 'Prato especial semanal.', 'Cozinhe feijão preto com carne seca, costelinha e linguiça por 2 horas. Sirva com arroz, couve e farofa.', '2026-07-31', true),
(158, 'U3B1ABL1000157', NULL, 'Marmita fit de tilápia', 'Linha leve do cardápio.', 'Grelhe o filé de tilápia com limão. Sirva com batata-doce assada, brócolis e arroz.', '2026-07-06', false),
(159, 'JU2F6JM1000126', NULL, 'Bife à parmegiana', 'Sucesso nas quartas-feiras.', 'Empane o bife com ovo e farinha de rosca e frite. Cubra com molho de tomate e mussarela e gratine no forno.', '2026-10-03', true),
(160, '96530289000120', NULL, 'Strogonoff de frango executivo', 'Prato com maior saída no almoço.', 'Prepare o strogonoff com frango em cubos, extrato de tomate, cogumelos e creme de leite. Sirva com arroz branco.', '2026-10-04', false),
(161, 'M2EKV6Q1000130', NULL, 'Kit churrasco tradicional', 'Kit vendido aos finais de semana.', 'Separar picanha em peça, linguiça toscana, queijo coalho e sal grosso e embalar a vácuo com a farofa pronta.', '2026-05-19', true),
(162, 'BT5YRER1000150', NULL, 'Espetinho de kafta', 'Produto pronto para a grelha.', 'Intercale a kafta bovina com cebola, pimentão e tomate nos espetos e mantenha refrigerado até a venda.', '2026-08-14', true),
(163, '0KXBOMS1000165', NULL, 'Costela assada 12 horas', 'Encomenda para eventos.', 'Tempere a costela com sal grosso, mix de churrasco e alho. Cubra com papel alumínio e asse em fogo baixo por 12 horas.', '2026-09-22', false),
(164, 'PAPPKUT1000110', NULL, 'Hambúrguer artesanal da casa', 'Blend próprio.', 'Misture carne moída com bacon picado, sal e pimenta, modele discos de 160 g e mantenha refrigerado.', '2026-09-14', true),
