(178, '7NKLRSF2000108', NULL, 'Combo lanche rápido', 'Cachorro-quente com refrigerante.', 'Aqueça a salsicha, coloque no pão de hot dog, finalize com maionese, ketchup e mostarda e sirva com refrigerante em lata.', '2026-07-06', true),
(179, 'WDCZN0H2000117', NULL, 'Misto frio da casa', 'Sanduíche pronto na geladeira.', 'Monte o sanduíche com pão de forma, presunto, mussarela e maionese, embale e mantenha refrigerado.', '2026-10-03', false),
(180, 'L44DK8I2000109', NULL, 'Combo lanche rápido', 'Cachorro-quente com refrigerante.', 'Aqueça a salsicha, coloque no pão de hot dog, finalize com maionese, ketchup e mostarda e sirva com refrigerante em lata.', '2026-10-04', true),
(181, 'ZLN4DOK2000153', NULL, 'Hot dog completo', 'Mais vendido do balcão.', 'Cozinhe a salsicha no molho, coloque no pão e cubra com milho, ervilha, batata palha, maionese, ketchup e mostarda.', '2026-05-19', false),
(182, '97037760000105', NULL, 'Misto quente americano', 'Chapa tradicional.', 'Passe manteiga nas duas faces do pão de forma, recheie com presunto e queijo e toste na chapa até dourar.', '2026-08-14', true),
(183, 'D37W54N2000151', NULL, 'X-burger da casa', 'Preparado na chapa.', 'Grelhe o hambúrguer na chapa, derreta o queijo, monte no pão com alface, tomate e maionese.', '2026-09-22', true),
(184, '2UY92CO2000140', NULL, 'Pastel de carne', 'Frito na hora.', 'Recheie o pastel com carne moída refogada com cebola, feche e frite em óleo quente até dourar.', '2026-09-14', false),
(185, 'GBI1VRQ2000107', NULL, 'Açaí na tigela com frutas', 'Opção fria da lanchonete.', 'Bata a polpa de açaí com banana, sirva na tigela com morango e aveia.', '2026-06-09', true),
(186, '52AFRZR2000112', NULL, 'Hot dog completo', 'Mais vendido do balcão.', 'Cozinhe a salsicha no molho, coloque no pão e cubra com milho, ervilha, batata palha, maionese, ketchup e mostarda.', '2026-09-09', false),
(187, 'US1TN7T2000192', NULL, 'Misto quente americano', 'Chapa tradicional.', 'Passe manteiga nas duas faces do pão de forma, recheie com presunto e queijo e toste na chapa até dourar.', '2026-09-02', true),
(188, '94445050000126', NULL, 'Arroz branco para 100 porções', 'Base de qualquer evento.', 'Refogue alho e cebola em óleo, junte o arroz, mexa e adicione água fervente na proporção 1 para 2. Cozinhe tampado até secar.', '2026-09-18', false),
(189, 'X0DYCVW2000170', NULL, 'Frango assado para eventos', 'Item fixo dos cardápios.', 'Tempere as coxas e sobrecoxas com tempero completo, alho e sal, descanse por 2 horas e asse a 200 graus por 1 hora.', '2026-08-19', true),
(190, 'MR4C93Y2000107', NULL, 'Lasanha de carne em bandeja', 'Produção em lote.', 'Monte camadas de massa, carne moída ao molho, presunto e mussarela em bandejas e asse por 40 minutos.', '2026-07-24', true),
(191, 'BIWP5BZ2000110', NULL, 'Salpicão de frango', 'Prato frio para eventos.', 'Misture frango desfiado cozido com cenoura ralada, milho, ervilha e maçã picada. Tempere com maionese e leve à geladeira.', '2026-08-29', false),
(192, '09O32J03000143', NULL, 'Arroz branco para 100 porções', 'Base de qualquer evento.', 'Refogue alho e cebola em óleo, junte o arroz, mexa e adicione água fervente na proporção 1 para 2. Cozinhe tampado até secar.', '2026-09-27', true),
(193, '91565901000186', NULL, 'Risoto de camarão', 'Prato nobre do menu.', 'Refogue cebola na manteiga, junte o arroz, deglaceie com vinho e acrescente caldo aos poucos. Finalize com camarões salteados e parmesão.', '2026-03-08', false),
(194, '3HZ8R643000150', NULL, 'Filé ao molho madeira', 'Clássico do almoço executivo.', 'Grelhe o filé mignon no ponto, prepare o molho com vinho, cebola, cogumelos e manteiga e sirva sobre o filé.', '2025-12-07', true),
(195, 'S7RMNE53000127', NULL, 'Salmão com purê de mandioca', 'Indicação do chef.', 'Grelhe o salmão com sal e limão. Amasse a mandioca cozida com manteiga e sirva com fio de azeite.', '2026-08-07', false),
(196, 'HYI0KM63000160', NULL, 'Espaguete ao sugo', 'Massa tradicional da cantina.', 'Cozinhe o espaguete al dente. Refogue alho no azeite, junte tomate pelado e deixe apurar. Misture a massa e finalize com parmesão.', '2026-10-01', true),
(197, 'VF2SC293000137', NULL, 'Bacalhau à Gomes de Sá', 'Prato de sexta-feira.', 'Cozinhe o bacalhau dessalgado e desfie. Refogue cebola no azeite, misture com batatas cozidas, azeitonas pretas e leve ao forno com ovos cozidos por cima.', '2026-07-31', true),
(198, 'K6U59AA3000123', NULL, 'Tiramisù da casa', 'Sobremesa assinatura.', 'Bata cream cheese com ovos e açúcar até obter creme. Molhe a base em café forte, monte camadas com o creme e finalize com cacau em pó.', '2026-07-06', false),
(199, '98643361000150', NULL, 'Risoto de camarão', 'Prato nobre do menu.', 'Refogue cebola na manteiga, junte o arroz, deglaceie com vinho e acrescente caldo aos poucos. Finalize com camarões salteados e parmesão.', '2026-10-03', true),
